import fs from "node:fs";
import path from "node:path";

const ROOT = process.cwd();
const REVISION = "v4-3-real-time-hardening-r1";
const BACKUP_SUFFIX = ".pre-studio-v4-3-real-time-hardening.bak";

const FILES = {
  "dsp/studio/mvp_studio_dsp.cpp": "",
  "public/audio/mvpStudioEngine.wasm": "",
  "src/lib/audio/mvpStudioEngine.ts": "",
  "src/lib/audio/mvpStudioDsp.worklet.js": ""
};

function fail(message) {
  console.error(`MVP Studio V4.3 installer stopped: ${message}`);
  console.error("Nothing was committed.");
  process.exit(1);
}

function readText(rel) {
  const full = path.join(ROOT, rel);
  if (!fs.existsSync(full)) fail(`required file not found: ${rel}`);
  return fs.readFileSync(full, "utf8");
}

const cpp = readText("dsp/studio/mvp_studio_dsp.cpp");
const engine = readText("src/lib/audio/mvpStudioEngine.ts");
const worklet = readText("src/lib/audio/mvpStudioDsp.worklet.js");

if (
  cpp.includes("eqTopologyTransitionPhase") &&
  worklet.includes("studio-wasm-v4.3-real-time-hardening") &&
  engine.includes('"4.3.0"')
) {
  console.log("MVP Studio V4.3 Real-Time Hardening is already installed.");
  process.exit(0);
}

// Baseline guards: V4 Mastering core must be present.
if (!cpp.includes("MVP Studio V4 Mastering Refinement")) {
  fail("V4 Mastering C++ baseline marker was not found.");
}
if (!worklet.includes("MVP Studio WASM AudioWorklet V4 Mastering Refinement")) {
  fail("V4 Mastering AudioWorklet baseline marker was not found.");
}
if (!worklet.includes('version: "studio-wasm-v4-mastering-refinement"')) {
  fail("V4 AudioWorklet runtime version marker was not found.");
}
if (!engine.includes('url.searchParams.set("v", "4.0.0")')) {
  fail("V4 Studio engine cache-version baseline was not found.");
}
if (!cpp.includes("mvp_commit_eq")) {
  fail("Studio FIR commit export was not found.");
}
if (!worklet.includes("mvp_commit_eq")) {
  fail("Studio worklet FIR commit bridge was not found.");
}

// Decode everything first, before touching the repo.
const decoded = new Map();
for (const [rel, b64] of Object.entries(FILES)) {
  decoded.set(rel, Buffer.from(b64, "base64"));
}

const tempFiles = [];
try {
  // Stage temp files beside their final targets.
  for (const [rel, bytes] of decoded.entries()) {
    const full = path.join(ROOT, rel);
    if (!fs.existsSync(full)) fail(`required destination file not found: ${rel}`);
    const tmp = `${full}.v43tmp`;
    fs.writeFileSync(tmp, bytes);
    tempFiles.push(tmp);
  }

  // Back up current V4 files before replacement.
  for (const rel of decoded.keys()) {
    const full = path.join(ROOT, rel);
    const backup = `${full}${BACKUP_SUFFIX}`;
    fs.copyFileSync(full, backup);
  }

  // Replace atomically on the same filesystem.
  for (const rel of decoded.keys()) {
    const full = path.join(ROOT, rel);
    const tmp = `${full}.v43tmp`;
    fs.renameSync(tmp, full);
  }
} catch (error) {
  for (const tmp of tempFiles) {
    try { if (fs.existsSync(tmp)) fs.unlinkSync(tmp); } catch {}
  }
  fail(error instanceof Error ? error.message : String(error));
}

console.log("MVP Studio V4.3 Real-Time Hardening applied successfully.");
console.log(`(${REVISION})`);
console.log("Updated complete Studio core files:");
console.log("  dsp/studio/mvp_studio_dsp.cpp");
console.log("  public/audio/mvpStudioEngine.wasm");
console.log("  src/lib/audio/mvpStudioEngine.ts");
console.log("  src/lib/audio/mvpStudioDsp.worklet.js");
console.log("Real-time changes:");
console.log("  - rapid UI state changes are coalesced at audio-block boundaries");
console.log("  - only changed WASM parameters are updated");
console.log("  - Minimum Phase EQ changes no longer rebuild the unused Linear FIR");
console.log("  - Linear FIR redesign waits ~120 ms after slider activity settles");
console.log("  - Minimum/Linear topology switching uses a short click-safe fade transition");
console.log(`Backups: *${BACKUP_SUFFIX}`);
console.log("NEXT: run npm run build");
